typescript:
=== SCAFFOLD ===
function two_sum(nums: number[], target: number): number[] {
  return [];
}
=== SOLUTION ===
function two_sum(nums: number[], target: number): number[] {
  const seen = new Map<number, number>();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need) as number, i];
    seen.set(nums[i], i);
  }
  return [];
}
